import argparse
import json
import unittest
from unittest import mock

from tmpl_survey import stack_path_lookup as spl
from tmpl_survey import stack_path_verbose_payload as spvp

_TARGET_PATH = "D/נוסח/ש"


def _fixture_from_d_column(d_col_wtseq):
    return {
        "book39s": [
            {
                "book24_name": "ספר מבחן",
                "sub_book_name": None,
                "chapters": {
                    "1": {
                        "1": [[], d_col_wtseq, []],
                    }
                },
            }
        ]
    }


class TestStackPathLookup(unittest.TestCase):
    def _search_with_fixture(
        self,
        fixture,
        *,
        dataset_key,
        target_path=_TARGET_PATH,
        verbose=False,
        limit=10,
    ):
        fixture_json = json.dumps(fixture, ensure_ascii=False)
        with (
            mock.patch.object(spl, "_dataset_file_paths", return_value=["dummy.json"]),
            mock.patch("builtins.open", mock.mock_open(read_data=fixture_json)),
        ):
            return spl.search_stack_path(
                target_path,
                dataset_key,
                limit,
                verbose=verbose,
            )

    def test_non_verbose_hit_is_occurrence_with_verse_metadata(self):
        fixture = _fixture_from_d_column(
            [
                {
                    "tmpl": [
                        ["נוסח"],
                        ["אאא"],
                        [{"stmpl": "ש"}],
                    ]
                }
            ]
        )

        hits = self._search_with_fixture(fixture, dataset_key="plain", verbose=False)

        self.assertEqual(1, len(hits))
        self.assertEqual(
            {
                "dataset": "plain",
                "bk24na": "ספר מבחן",
                "sub_bkna": None,
                "chnu": "1",
                "psv_psn": "1",
                "stack_path": _TARGET_PATH,
            },
            hits[0],
        )

    def test_verbose_returns_one_hit_per_match_occurrence(self):
        fixture = _fixture_from_d_column(
            [
                {
                    "tmpl_name": "נוסח",
                    "tmpl_params": {
                        "1": "א",
                        "2": {"tmpl_name": "ש"},
                    },
                },
                {
                    "tmpl_name": "נוסח",
                    "tmpl_params": {
                        "1": "ב",
                        "2": {"tmpl_name": "ש", "tmpl_params": {"1": "ג"}},
                    },
                },
            ]
        )

        hits = self._search_with_fixture(
            fixture,
            dataset_key="plus",
            verbose=True,
        )

        self.assertEqual(2, len(hits))

        expected_keys = {
            "dataset",
            "bk24na",
            "sub_bkna",
            "chnu",
            "psv_psn",
            "stack_path",
            "path_root_wikitext",
            "path_root_json",
        }

        for hit in hits:
            self.assertEqual(expected_keys, set(hit.keys()))
            self.assertEqual("plus", hit["dataset"])
            self.assertEqual("ספר מבחן", hit["bk24na"])
            self.assertEqual(None, hit["sub_bkna"])
            self.assertEqual("1", hit["chnu"])
            self.assertEqual("1", hit["psv_psn"])
            self.assertEqual(_TARGET_PATH, hit["stack_path"])
            self.assertIn("path_root_wikitext", hit)
            self.assertIn("path_root_json", hit)
            self.assertEqual("נוסח", hit["path_root_json"]["tmpl_name"])

        root_wikitexts = {hit["path_root_wikitext"] for hit in hits}
        self.assertEqual(
            {
                "{{נוסח|א|{{ש}}}}",
                "{{נוסח|ב|{{ש|ג}}}}",
            },
            root_wikitexts,
        )

    def test_plus_tree_deparse_handles_nested_templates(self):
        match_tree = {
            "tmpl_name": "כו״ק",
            "tmpl_params": {
                "1": {
                    "tmpl_name": "מ:קמץ",
                    "tmpl_params": {
                        "1": "אאא",
                        "2": "בבב",
                    },
                },
                "2": "גגג",
            },
        }

        self.assertEqual(
            "{{כו״ק|{{מ:קמץ|אאא|בבב}}|גגג}}",
            spvp.wtel_to_wikitext_plus(match_tree),
        )

    def test_verbose_flag_requires_target_path(self):
        parser = argparse.ArgumentParser()
        spl.add_parser_args(parser)

        with self.assertRaises(SystemExit):
            parser.parse_args(["--find-stack-path-verbose"])

    def test_verbose_variant_accepts_direct_path_argument(self):
        parser = argparse.ArgumentParser()
        spl.add_parser_args(parser)
        args = parser.parse_args(["--find-stack-path-verbose", _TARGET_PATH])

        with (
            mock.patch.object(spl, "search_stack_path", return_value=[]) as mock_search,
            mock.patch.object(spl, "print_results") as mock_print,
        ):
            handled = spl.maybe_handle_cli(parser, args)

        self.assertTrue(handled)
        mock_search.assert_called_once_with(
            _TARGET_PATH,
            "plus",
            10,
            verbose=True,
        )
        mock_print.assert_called_once()

    def test_plain_and_verbose_variants_are_mutually_exclusive(self):
        parser = argparse.ArgumentParser()
        spl.add_parser_args(parser)
        args = parser.parse_args(
            [
                "--find-stack-path",
                _TARGET_PATH,
                "--find-stack-path-verbose",
                _TARGET_PATH,
            ]
        )

        with self.assertRaises(SystemExit):
            spl.maybe_handle_cli(parser, args)

    def test_docnote_path_matches_arg_1_and_arg_2(self):
        fixture = {
            "book39s": [
                {
                    "book24_name": "ספר מבחן",
                    "sub_book_name": None,
                    "chapters": {
                        "1": {
                            "1": [
                                [],
                                [
                                    {
                                        "tmpl_name": "נוסח",
                                        "tmpl_params": {
                                            "1": {"tmpl_name": "ש"},
                                            "2": "א",
                                        },
                                    }
                                ],
                                [],
                            ],
                            "2": [
                                [],
                                [
                                    {
                                        "tmpl_name": "נוסח",
                                        "tmpl_params": {
                                            "1": "ב",
                                            "2": {"tmpl_name": "ש"},
                                        },
                                    }
                                ],
                                [],
                            ],
                        }
                    },
                }
            ]
        }

        hits = self._search_with_fixture(
            fixture,
            dataset_key="plus",
            target_path="D/נוסח/ש",
        )

        self.assertEqual(2, len(hits))
        self.assertEqual("1", hits[0]["psv_psn"])
        self.assertEqual("2", hits[1]["psv_psn"])

    def test_path_match_is_exact(self):
        self.assertFalse(spl._path_matches(("D", "נוסח"), "ש", "D/מ:כפול/ש"))
        self.assertTrue(
            spl._path_matches(
                ("D", "נוסח"),
                "ש",
                "D/נוסח/ש",
            )
        )
